import type { IPipeableAsyncIterable, IPipeOp, ITermOp, TAnySource, TPipeElementOf, TPipeGrouped, TPipeGroupedTerm } from './types';
/**
 * Anything `pipe` and `from` accept as the head of a pipeline.
 *
 * A single promise yields its resolved value; anything that is neither iterable nor thenable is a
 * `TypeError` when the pipeline is driven.
 */
export type TPipeSource<T> = TAnySource<T>;
/**
 * Run a pipeline over a source, the shape every `pipe` overload resolves to.
 *
 * The overload ladder covers bare operators only, so the array-grouped form reaches this with parts
 * the types never inspected. The terminal-not-last throw is the backstop for that form.
 */
export declare function applyPipe(source: TPipeSource<unknown>, parts: unknown[]): unknown;
/**
 * Factory to create a pipeable async iterable wrapper with .pipe method.
 * Delegates iteration to the wrapped async iterable, carries the PIPEABLE brand,
 * and exposes only `.pipe(...)` method (no terminal methods).
 */
export declare function makePipeable<T>(asyncIterable: AsyncIterable<T>): IPipeableAsyncIterable<T>;
/**
 * Pipe a source through operators and optionally a terminal.
 *
 * `pipe(source)` and `pipe(source, ...ops)` return a pipeable `AsyncIterable`, lazy until something
 * consumes it. `pipe(source, ...ops, terminal)` returns the terminal's promise instead.
 *
 * The overloads thread the element type from the source through every operator, so a terminal that
 * is not last, or a second terminal, matches no overload. The array-grouped form
 * `pipe(source, [op1, op2], terminal)` is threaded by a recursive type instead, and keeps the
 * runtime check as its backstop.
 *
 * An optional config object is accepted as the last argument only. Any other argument that is not
 * an operator or a terminal is a `TypeError`.
 */
export declare function pipe<A>(source: TPipeSource<A>): IPipeableAsyncIterable<A>;
export declare function pipe<A, R>(source: TPipeSource<A>, term: ITermOp<A, R>): PromiseLike<R>;
export declare function pipe<A, B1>(source: TPipeSource<A>, op1: IPipeOp<A, B1>): IPipeableAsyncIterable<B1>;
export declare function pipe<A, B1, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, term: ITermOp<B1, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>): IPipeableAsyncIterable<B2>;
export declare function pipe<A, B1, B2, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, term: ITermOp<B2, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2, B3>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>): IPipeableAsyncIterable<B3>;
export declare function pipe<A, B1, B2, B3, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, term: ITermOp<B3, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2, B3, B4>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>): IPipeableAsyncIterable<B4>;
export declare function pipe<A, B1, B2, B3, B4, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, term: ITermOp<B4, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2, B3, B4, B5>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>): IPipeableAsyncIterable<B5>;
export declare function pipe<A, B1, B2, B3, B4, B5, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, term: ITermOp<B5, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>): IPipeableAsyncIterable<B6>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>, term: ITermOp<B6, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6, B7>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>, op7: IPipeOp<B6, B7>): IPipeableAsyncIterable<B7>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6, B7, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>, op7: IPipeOp<B6, B7>, term: ITermOp<B7, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6, B7, B8>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>, op7: IPipeOp<B6, B7>, op8: IPipeOp<B7, B8>): IPipeableAsyncIterable<B8>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6, B7, B8, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>, op7: IPipeOp<B6, B7>, op8: IPipeOp<B7, B8>, term: ITermOp<B8, R>): PromiseLike<R>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6, B7, B8, B9>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>, op7: IPipeOp<B6, B7>, op8: IPipeOp<B7, B8>, op9: IPipeOp<B8, B9>): IPipeableAsyncIterable<B9>;
export declare function pipe<A, B1, B2, B3, B4, B5, B6, B7, B8, B9, R>(source: TPipeSource<A>, op1: IPipeOp<A, B1>, op2: IPipeOp<B1, B2>, op3: IPipeOp<B2, B3>, op4: IPipeOp<B3, B4>, op5: IPipeOp<B4, B5>, op6: IPipeOp<B5, B6>, op7: IPipeOp<B6, B7>, op8: IPipeOp<B7, B8>, op9: IPipeOp<B8, B9>, term: ITermOp<B9, R>): PromiseLike<R>;
/**
 * Array-grouped form, which the ladder above does not cover.
 *
 * The operator list is walked recursively, so the element type threads through a group the same way
 * it threads through bare operators, and a group that does not line up resolves to `never`.
 *
 * One boundary is worth knowing: an array literal nested inside another array literal infers as an
 * array rather than as a tuple, so its operators are not checked against each other in order. An
 * inline arrow inside a group has no contextual parameter type for the same reason, and needs an
 * annotation or a named callback.
 */
export declare function pipe<A, TOps extends readonly unknown[], R>(source: TPipeSource<A>, ops: readonly [...TOps], term: ITermOp<TPipeElementOf<A, TOps>, R>): TPipeGroupedTerm<A, TOps, R>;
export declare function pipe<A, TOps extends readonly unknown[]>(source: TPipeSource<A>, ops: readonly [...TOps]): TPipeGrouped<A, TOps>;
